from dataclasses import dataclass

@dataclass(frozen=True)
class Subscription:
    tier: str
    started_at: date

def decide_charge(sub: Subscription, now: date):     # pure: no clock, no repo
    monthly = {"pro": 2900, "team": 9900}.get(sub.tier, 0)
    if not monthly: return NoCharge()
    return Charge(amount_cents=round(monthly * (now - sub.started_at).days / 30))
# shell: sub = repo.load(user_id); apply(decide_charge(sub, date.today()))
